@cuda.jit(device=True, forceinline=True)
def _b1024_panel_load_factor_tile(
    source, sample_base, tile_row, tile_col, shared
):
    tid = cuda.threadIdx.x
    row_origin = tile_row * _D256_NB
    col_origin = tile_col * _D256_NB
    row = tid // _D256_NB
    col = tid - row * _D256_NB
    shared_index = row * _B1024_FP32_LD + col
    source_index = (
        sample_base + (row_origin + row) * _D256_N + col_origin + col
    )
    for _ in range(_B1024_LOADS_PER_THREAD):
        shared[shared_index] = source[source_index]
        shared_index += _B1024_ROW_STRIDE * _B1024_FP32_LD
        source_index += _B1024_GLOBAL_ROW_STRIDE
    cuda.syncthreads()


